files.content:
:root {
  --bg: #1a1c2c;
  --card-bg: #2a2d45;
  --primary: #ffcd75;
  --accent: #38b764;
  --text: #f4f4f4;
  --muted: #a0a0b0;
  --border: #5a5e7a;
  --font: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  background-color: var(--bg);
  background-image: 
    linear-gradient(45deg, #22243a 25%, transparent 25%),
    linear-gradient(-45deg, #22243a 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #22243a 75%),
    linear-gradient(-45deg, transparent 75%, #22243a 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--border);
  border-radius: 0;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.5);
  width: 100%;
  max-width: 600px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.header h1 {
  font-size: 28px;
  color: var(--primary);
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 4px;
}

.subtitle {
  color: var(--muted);
  font-size: 16px;
}

.items-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 12px;
}

.item-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px;
  background: #22243a;
  border: 2px solid var(--border);
  padding: 12px;
  align-items: end;
}

.item-fields {
  display: grid;
  grid-template-columns: 1fr 80px 100px;
  gap: 8px;
}

.field-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.field-group label {
  font-size: 14px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.field-group input {
  font-family: var(--font);
  font-size: 16px;
  padding: 8px;
  background: var(--bg);
  border: 2px solid var(--border);
  color: var(--text);
  border-radius: 0;
  width: 100%;
}

.field-group input:focus {
  outline: 3px solid var(--primary);
  outline-offset: 1px;
  border-color: var(--primary);
}

.line-total {
  font-size: 16px;
  color: var(--accent);
  text-align: right;
  padding-bottom: 8px;
  white-space: nowrap;
}

.btn {
  font-family: var(--font);
  font-size: 16px;
  padding: 10px 16px;
  border: 3px solid var(--border);
  background: var(--card-bg);
  color: var(--text);
  cursor: pointer;
  border-radius: 0;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: background 0.1s, transform 0.1s;
}

.btn:hover {
  background: #3a3d55;
  border-color: var(--primary);
}

.btn:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.btn:active {
  transform: translate(2px, 2px);
  box-shadow: none;
}

.btn-add {
  width: 100%;
  border-color: var(--accent);
  color: var(--accent);
}

.btn-add:hover {
  background: #2a4a3a;
}

.btn-remove {
  padding: 8px 12px;
  border-color: #e43b44;
  color: #e43b44;
  font-size: 14px;
  align-self: end;
  margin-bottom: 2px;
}

.btn-remove:hover {
  background: #4a2a2a;
}

.totals-grid {
  display: flex;
  flex-direction: column;
  gap: 8px;
  border-top: 4px solid var(--border);
  padding-top: 16px;
}

.total-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 16px;
  padding: 4px 0;
}

.tax-row label {
  color: var(--muted);
}

.tax-row input {
  width: 80px;
  font-family: var(--font);
  font-size: 16px;
  padding: 6px 8px;
  background: var(--bg);
  border: 2px solid var(--border);
  color: var(--text);
  text-align: right;
  border-radius: 0;
}

.tax-row input:focus {
  outline: 3px solid var(--primary);
  outline-offset: 1px;
  border-color: var(--primary);
}

.grand-total {
  font-size: 20px;
  color: var(--primary);
  border-top: 2px dashed var(--border);
  padding-top: 12px;
  margin-top: 4px;
  font-weight: bold;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 480px) {
  .card {
    padding: 16px;
  }
  .item-fields {
    grid-template-columns: 1fr 1fr;
  }
  .item-fields .field-group:first-child {
    grid-column: 1 / -1;
  }
  .item-row {
    grid-template-columns: 1fr;
  }
  .btn-remove {
    width: 100%;
    margin-top: 8px;
  }
  .line-total {
    text-align: left;
    padding-bottom: 0;
  }
}

let itemCounter = 0;

const itemsList = document.getElementById('items-list');
const addBtn = document.getElementById('add-item');
const taxInput = document.getElementById('tax-rate');
const subtotalEl = document.getElementById('subtotal');
const taxAmountEl = document.getElementById('tax-amount');
const grandTotalEl = document.getElementById('grand-total');

function formatCurrency(value) {
  return '$' + value.toFixed(2);
}

function createItemRow() {
  itemCounter++;
  const rowId = 'item-' + itemCounter;
  const row = document.createElement('div');
  row.className = 'item-row';
  row.id = rowId;

  row.innerHTML = `
    <div class="item-fields">
      <div class="field-group">
        <label for="desc-${rowId}">Description</label>
        <input type="text" id="desc-${rowId}" class="item-desc" placeholder="Item description" aria-label="Item description">
      </div>
      <div class="field-group">
        <label for="qty-${rowId}">Qty</label>
        <input type="number" id="qty-${rowId}" class="item-qty" min="1" value="1" aria-label="Quantity">
      </div>
      <div class="field-group">
        <label for="price-${rowId}">Unit Price</label>
        <input type="number" id="price-${rowId}" class="item-price" min="0" step="0.01" value="0.00" aria-label="Unit price">
      </div>
    </div>
    <span class="line-total" aria-live="polite">$0.00</span>
    <button type="button" class="btn btn-remove" aria-label="Remove item">Remove</button>
  `;

  const descInput = row.querySelector('.item-desc');
  const qtyInput = row.querySelector('.item-qty');
  const priceInput = row.querySelector('.item-price');
  const lineTotalEl = row.querySelector('.line-total');
  const removeBtn = row.querySelector('.btn-remove');

  function updateLineTotal() {
    const qty = parseFloat(qtyInput.value) || 0;
    const price = parseFloat(priceInput.value) || 0;
    const total = qty * price;
    lineTotalEl.textContent = formatCurrency(total);
    updateTotals();
  }

  qtyInput.addEventListener('input', updateLineTotal);
  priceInput.addEventListener('input', updateLineTotal);

  removeBtn.addEventListener('click', function () {
    row.remove();
    updateTotals();
  });

  updateLineTotal();
  return row;
}

function updateTotals() {
  let subtotal = 0;
  const rows = itemsList.querySelectorAll('.item-row');
  rows.forEach(function (row) {
    const qty = parseFloat(row.querySelector('.item-qty').value) || 0;
    const price = parseFloat(row.querySelector('.item-price').value) || 0;
    subtotal += qty * price;
  });

  const taxRate = parseFloat(taxInput.value) || 0;
  const tax = subtotal * (taxRate / 100);
  const grandTotal = subtotal + tax;

  subtotalEl.textContent = formatCurrency(subtotal);
  taxAmountEl.textContent = formatCurrency(tax);
  grandTotalEl.textContent = formatCurrency(grandTotal);
}

addBtn.addEventListener('click', function () {
  const row = createItemRow();
  itemsList.appendChild(row);
  const firstInput = row.querySelector('.item-desc');
  if (firstInput) firstInput.focus();
});

taxInput.addEventListener('input', updateTotals);

// Initialize with one empty row
addBtn.click();
